CREATE TYPE "AiPromotionMode" AS ENUM ('AI','MOTION','HYBRID');
CREATE TYPE "AiPromotionScope" AS ENUM ('PRODUCT','STORE');
CREATE TYPE "AiPromotionStatus" AS ENUM ('DRAFT','QUEUED','PROCESSING','READY','FAILED','ARCHIVED');
CREATE TYPE "AiPromotionJobStatus" AS ENUM ('QUEUED','PROCESSING','SUCCEEDED','FAILED');
CREATE TYPE "AiPromotionAssetType" AS ENUM ('SOURCE_IMAGE','GENERATED_IMAGE','VIDEO','POSTER','SCRIPT');
CREATE TABLE "AiPromotionProject" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"connectionId" TEXT NOT NULL,"postId" TEXT,"title" TEXT NOT NULL,"scope" "AiPromotionScope" NOT NULL DEFAULT 'PRODUCT',"mode" "AiPromotionMode" NOT NULL DEFAULT 'HYBRID',"durationSeconds" INTEGER NOT NULL DEFAULT 15,"aspectRatio" TEXT NOT NULL DEFAULT '9:16',"width" INTEGER NOT NULL DEFAULT 1080,"height" INTEGER NOT NULL DEFAULT 1920,"prompt" TEXT NOT NULL,"status" "AiPromotionStatus" NOT NULL DEFAULT 'DRAFT',"idempotencyKey" TEXT,"provider" TEXT,"providerJobId" TEXT,"errorCode" TEXT,"errorMessage" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"completedAt" TIMESTAMP(3),CONSTRAINT "AiPromotionProject_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AiPromotionJob" ("id" TEXT NOT NULL,"projectId" TEXT NOT NULL,"status" "AiPromotionJobStatus" NOT NULL DEFAULT 'QUEUED',"attempts" INTEGER NOT NULL DEFAULT 0,"maxAttempts" INTEGER NOT NULL DEFAULT 3,"availableAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lockedAt" TIMESTAMP(3),"workerId" TEXT,"lastError" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AiPromotionJob_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AiPromotionAsset" ("id" TEXT NOT NULL,"projectId" TEXT NOT NULL,"type" "AiPromotionAssetType" NOT NULL,"storageKey" TEXT NOT NULL,"contentType" TEXT NOT NULL,"width" INTEGER,"height" INTEGER,"durationMs" INTEGER,"byteSize" BIGINT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AiPromotionAsset_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "AiPromotionProject_userId_idempotencyKey_key" ON "AiPromotionProject"("userId","idempotencyKey");
CREATE INDEX "AiPromotionProject_userId_createdAt_idx" ON "AiPromotionProject"("userId","createdAt");
CREATE INDEX "AiPromotionProject_connectionId_status_idx" ON "AiPromotionProject"("connectionId","status");
CREATE INDEX "AiPromotionProject_status_createdAt_idx" ON "AiPromotionProject"("status","createdAt");
CREATE INDEX "AiPromotionJob_status_availableAt_idx" ON "AiPromotionJob"("status","availableAt");
CREATE INDEX "AiPromotionJob_projectId_createdAt_idx" ON "AiPromotionJob"("projectId","createdAt");
CREATE INDEX "AiPromotionAsset_projectId_type_idx" ON "AiPromotionAsset"("projectId","type");
ALTER TABLE "AiPromotionProject" ADD CONSTRAINT "AiPromotionProject_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AiPromotionProject" ADD CONSTRAINT "AiPromotionProject_connectionId_fkey" FOREIGN KEY ("connectionId") REFERENCES "InstagramConnection"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AiPromotionProject" ADD CONSTRAINT "AiPromotionProject_postId_fkey" FOREIGN KEY ("postId") REFERENCES "InstagramPost"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "AiPromotionJob" ADD CONSTRAINT "AiPromotionJob_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "AiPromotionProject"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AiPromotionAsset" ADD CONSTRAINT "AiPromotionAsset_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "AiPromotionProject"("id") ON DELETE CASCADE ON UPDATE CASCADE;
